81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    /**
89	     * Store the email address lower-cased, so it is persisted and returned in a
90	     * canonical form regardless of the casing supplied by the caller.
91	     */
92	    public void setEmail(String email) {
93	        this.email = email == null ? null : email.toLowerCase();
94	    }
95	
96	    protected Set<Pet> getPetsInternal() {
97	        if (this.pets == null) {
98	            this.pets = new HashSet<>();
99	        }
100	        return this.pets;
101	    }
102	
103	    protected void setPetsInternal(Set<Pet> pets) {
104	        this.pets = pets;
105	    }
106	
107	    public List<Pet> getPets() {
108	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
109	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
110	        return Collections.unmodifiableList(sortedPets);
111	    }
