133	     * Return the Pet with the given name, or null if none found for this Owner.
134	     *
135	     * @param name to test
136	     * @return true if pet name is already in use
137	     */
138	    public Pet getPet(String name, boolean ignoreNew) {
139	        name = name.toLowerCase();
140	        for (Pet pet : getPetsInternal()) {
141	            if (!ignoreNew || !pet.isNew()) {
142	                String compName = pet.getName();
143	                compName = compName.toLowerCase();
144	                if (compName.equals(name)) {
145	                    return pet;
146	                }
147	            }
148	        }
149	        return null;
150	    }
